struct Fixture {
    j: J,
    did: String,
    space: String,
    rev: String,
    key: vlsync_atproto::crypto::Keypair,
}

fn fixture() -> Fixture {
    let j: J = serde_json::from_str(EXPORT_JSON).unwrap();
    let key = vlsync_atproto::crypto::Keypair::from_bytes(&hex::decode(j["privateKeyHex"].as_str().unwrap()).unwrap())
        .unwrap();
    assert_eq!(key.did_key(), j["didKey"].as_str().unwrap(), "the fixture's key");
    Fixture {
        did: j["did"].as_str().unwrap().into(),
        space: j["space"].as_str().unwrap().into(),
        rev: j["rev"].as_str().unwrap().into(),
        key,
        j,
    }
}

/// The reference's CAR passes our port of verifyRepoCarFull, and the same
/// commit and records encode back to the same bytes: the reference and
/// vlpds agree on the export format (block order, index encoding, commit
/// encoding), which is what an import reads.
#[test]
fn reference_export_verifies_and_reencodes() {
    let f = fixture();
    let v = verify_repo_car(EXPORT_CAR, &f.space, &f.did, f.j["didKey"].as_str().unwrap(), true)
        .unwrap_or_else(|e| panic!("the reference's export doesn't verify: {e}"));
    assert_eq!(v.commit.rev, f.rev);
    assert_eq!(hex::encode(&v.commit.hash), f.j["hash"].as_str().unwrap());
    let want: Vec<(String, String)> = f.j["records"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| {
            (
                format!("{}/{}", r["collection"].as_str().unwrap(), r["rkey"].as_str().unwrap()),
                r["cid"].as_str().unwrap().to_string(),
            )
        })
        .collect();
    let mut sorted = want.clone();
    sorted.sort_by(|a, b| vlsync_atproto::cbor::key_cmp(&a.0, &b.0));
    let got: Vec<(String, String)> = v.index.iter().map(|(p, c)| (p.clone(), c.to_string())).collect();
    assert_eq!(got, sorted, "the index, in canonical (length-first) order");
    // the blob is named by a record, as a link
    let blob = f.j["blob"]["cid"].as_str().unwrap();
    assert!(v.records.iter().any(|(_, b)| Value::decode(b).unwrap().to_json().to_string().contains(blob)));

    let (roots, blocks) = vlsync_atproto::car::read_car(EXPORT_CAR).unwrap();
    assert_eq!(commit_block(&v.commit), blocks[0].1, "the commit block re-encodes byte for byte");
    assert_eq!(index_block(&v.index), blocks[1].1, "the index block re-encodes byte for byte");
    let owned: Vec<(Cid, Vec<u8>)> = blocks.iter().map(|(c, b)| (*c, b.to_vec())).collect();
    assert_eq!(write_car(&roots, &owned), EXPORT_CAR, "the CAR framing re-encodes byte for byte");

    // and a commit for another author or space, or a key that isn't the
    // DID's, is refused by the same checks
    let key = f.j["didKey"].as_str().unwrap();
    assert!(verify_repo_car(EXPORT_CAR, &f.space, "did:plc:someoneelse2345abcdefgh", key, true).is_err());
    assert!(verify_repo_car(EXPORT_CAR, &format!("{}x", f.space), &f.did, key, true).is_err());
    let other = vlsync_atproto::crypto::Keypair::generate().did_key();
    assert!(verify_repo_car(EXPORT_CAR, &f.space, &f.did, &other, true).is_err());
}

/// A reference-hosted account moves to vlpds with its space repo: created
/// with its DID, the DID moved and the account activated, then the
/// reference's getRepo CAR imported with OAuth under the key the DID held
/// at its rev (the old host's), the record's blob listed missing until
/// uploaded. vlpds then serves the same repo: the same rev, set hash,
/// index and record blocks, signed by its own key.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn reference_export_imports_mid_migration() {
    let f = fixture();
    let (plc, docs) = stub_plc().await;
    let new = stub_host(&plc, 1).await;
    let new_did = new.pds_did().await;
    // the DID's document on the reference host, before the move
    docs.lock().unwrap().insert(
        f.did.clone(),
        json!({
            "@context": ["https://www.w3.org/ns/did/v1"],
            "id": f.did,
            "alsoKnownAs": ["at://refexport.example"],
            "verificationMethod": [{
                "id": format!("{}#atproto", f.did), "type": "Multikey", "controller": f.did,
                "publicKeyMultibase": f.key.did_key().strip_prefix("did:key:").unwrap(),
            }],
            "service": [{"id": "#atproto_pds", "type": "AtprotoPersonalDataServer", "serviceEndpoint": "http://127.0.0.1:9"}],
        }),
    );
    let sa =
        vlpds::auth::service_auth_jwt(&f.key, &f.did, &new_did, Some("com.atproto.server.createAccount"), 60).unwrap();
    let a = arrive(&new, &f.did, sa).await;
    complete_move(&docs, &new, &a).await;
    let oauth = a.oauth(&new).await;

    let out = import_repo(&oauth, &f.space, EXPORT_CAR).await.ok();
    assert_eq!(out["rev"], json!(f.rev), "{out}");
    assert_eq!(out["records"], json!(5), "{out}");
    check_space_ok(&new, &f.did, &f.space).await;

    // the migration copies the record's blob, which listMissingBlobs names
    let blob = f.j["blob"]["cid"].as_str().unwrap().to_string();
    assert_eq!(missing_blobs(&new, &a.session).await, vec![blob.clone()]);
    let bytes = hex::decode(f.j["blob"]["bytesHex"].as_str().unwrap()).unwrap();
    let up = new.xrpc.post_bytes("com.atproto.repo.uploadBlob", bytes, "image/png", &a.session).await.ok();
    assert_eq!(up["blob"]["ref"]["$link"], json!(blob));
    assert!(missing_blobs(&new, &a.session).await.is_empty());
    assert_eq!(head(&oauth, &f.space).await.map(|h| h.0), Some(f.rev.clone()));
    let (_, hash) = head(&oauth, &f.space).await.unwrap();
    assert_eq!(hex::encode(hash), f.j["hash"].as_str().unwrap());
    expect_set_hash_matches_store(&oauth, &f.space).await;
    let r = get_repo_self(&oauth, &f.space).await;
    assert_eq!(r.status, 200, "{}", r.text());
    let mine = verify_repo_car(&r.body, &f.space, &f.did, &did_key(&new, &f.did).await, true)
        .unwrap_or_else(|e| panic!("vlpds's getRepo after the import doesn't verify: {e}"));
    let theirs = verify_repo_car(EXPORT_CAR, &f.space, &f.did, &f.key.did_key(), true).unwrap();
    assert_eq!(
        (mine.commit.rev.clone(), mine.commit.hash.clone()),
        (theirs.commit.rev.clone(), theirs.commit.hash.clone())
    );
    assert_eq!(mine.index_cid, theirs.index_cid, "the same index block");
    assert_eq!(mine.records, theirs.records, "the same record blocks, in the same order");
    let b = dpop_raw(
        &oauth,
        &new.url,
        reqwest::Method::GET,
        "com.atproto.space.getBlob",
        &[("space", &f.space), ("repo", &f.did), ("cid", &blob)],
        None,
    )
    .await;
    assert_eq!((b.status, b.body.to_vec()), (200, hex::decode(f.j["blob"]["bytesHex"].as_str().unwrap()).unwrap()));

    // the oplog starts empty at the imported rev; the next write follows it
    let ops = oauth.get("com.atproto.space.listRepoOps", &[("space", &f.space), ("repo", &f.did)]).await.ok();
    assert_eq!(ops["ops"], json!([]), "{ops}");
    assert_eq!(ops["commit"]["rev"], json!(f.rev), "{ops}");
    let w = write(&oauth, &f.space, W::new().rkey("after-import").text("written on vlpds")).await.ok();
    let (rev, _) = head(&oauth, &f.space).await.unwrap();
    assert!(rev > f.rev, "a write after the import moves past its rev: {rev} vs {}", f.rev);
    assert!(w["uri"].as_str().unwrap().ends_with("/after-import"), "{w}");
    let ops = oauth
        .get("com.atproto.space.listRepoOps", &[("space", &f.space), ("repo", &f.did), ("since", &f.rev)])
        .await
        .ok();
    let mut set = LtHash::default();
    for (p, c) in theirs.set() {
        let (coll, rkey) = p.split_once('/').unwrap();
        set.add(&vlpds::space::commit::element(coll, rkey, &c));
    }
    for op in ops["ops"].as_array().unwrap() {
        super::fuzz::fold(&mut set, op);
    }
    assert!(commit_matches(&set, &ops["commit"]), "the imported set plus the new ops is the head");
    check_space_ok(&new, &f.did, &f.space).await;
}

