/// Two hosts on the stub directory, bob moving from the first to the
/// second; alice governs a space on a third, bob (a member, on the first)
/// writes into it, carol (on the first) reads. The authority isn't on bob's
/// old host: these hosts run with unregistered DIDs, so that host would
/// keep verifying bob by its own document after he left, where a directory
/// host resolves the moved DID.
pub(super) struct TwoHosts {
    pub docs: Docs,
    pub a: TestServer,
    pub b: TestServer,
    /// alice's host.
    pub c: TestServer,
    pub alice: SpaceClient,
    pub bob: SpaceClient,
    pub carol: SpaceClient,
    pub space: String,
}

pub(super) async fn two_hosts() -> TwoHosts {
    let (plc, docs) = stub_plc().await;
    let (a, b, c) = (stub_host(&plc, 0).await, stub_host(&plc, 1).await, stub_host(&plc, 2).await);
    let mut who = Vec::new();
    for (name, host) in [("alice", &c), ("bob", &a), ("carol", &a)] {
        let sc = SpaceClient::new(host, &unique_name(name), FULL_SCOPE).await;
        publish(&docs, host, &sc.did).await;
        who.push(sc);
    }
    let carol = who.pop().unwrap();
    let bob = who.pop().unwrap();
    let alice = who.pop().unwrap();
    let space = format!("at://{}/space/{TEST_SPACE_TYPE}/{}", alice.did, unique_name("mv"));
    let skey = last_segment(&space).to_string();
    let r = alice
        .post(
            "com.atproto.simplespace.createSpace",
            json!({"spaceType": TEST_SPACE_TYPE, "skey": skey, "readPolicy": member_list(), "writePolicy": member_list(), "appAccess": open()}),
        )
        .await;
    assert_eq!(r.ok()["uri"], json!(space));
    for m in [&bob, &carol] {
        put_member(&alice, &space, m, true, true).await.ok();
    }
    TwoHosts { docs, a, b, c, alice, bob, carol, space }
}

/// bob's writes: creates, an update, a delete and a record naming a blob.
/// Returns the blob's CID and bytes.
pub(super) async fn fill_bob(h: &TwoHosts) -> (String, Vec<u8>) {
    for i in 0..6 {
        write(&h.bob, &h.space, W::new().rkey(&format!("r{i}")).text(&format!("bob {i}"))).await.ok();
    }
    put(&h.bob, &h.space, W::new().rkey("r1").text("bob 1, revised")).await.ok();
    del(&h.bob, &h.space, None, "r2").await.ok();
    let bytes = format!("\u{89}PNG\r\n\x1a\n bob's space image {}", unique_name("img")).into_bytes();
    let blob = upload_blob(&h.bob, &bytes).await;
    let rec = json!({"$type": TEST_COLLECTION, "text": "with an image", "image": blob});
    write(&h.bob, &h.space, W::new().rkey("img").record(rec)).await.ok();
    (blob_cid(&blob), bytes)
}

/// bob moves to host b: exported from host a, the DID switched and the
/// account activated on b, then his space repo imported there with his
/// OAuth grant (the first value) and its blobs copied as listMissingBlobs
/// asks.
pub(super) async fn move_bob(h: &TwoHosts, blob: &(String, Vec<u8>)) -> (SpaceClient, VerifiedRepo) {
    let b_did = h.b.pds_did().await;
    let sa = service_jwt(&h.bob, &b_did, "com.atproto.server.createAccount").await;
    let arrived = arrive(&h.b, &h.bob.did, sa).await;
    let r = get_repo_self(&h.bob, &h.space).await;
    assert_eq!(r.status, 200, "{}", r.text());
    let exported = verify_repo_car(&r.body, &h.space, &h.bob.did, &did_key(&h.a, &h.bob.did).await, true).unwrap();
    complete_move(&h.docs, &h.b, &arrived).await;
    let moved = arrived.oauth(&h.b).await;
    let out = import_repo(&moved, &h.space, &r.body).await.ok();
    assert_eq!(out["rev"], json!(exported.commit.rev), "{out}");
    assert_eq!(out["records"], json!(exported.index.len()), "{out}");
    // the blob from the old host's space.getBlob, as the migrate page copies it
    let (status, _, got) = h
        .bob
        .get_raw("com.atproto.space.getBlob", &[("space", &h.space), ("repo", &h.bob.did), ("cid", &blob.0)])
        .await;
    assert_eq!((status, &got), (200, &blob.1));
    assert_eq!(missing_blobs(&h.b, &arrived.session).await, vec![blob.0.clone()]);
    h.b.xrpc.post_bytes("com.atproto.repo.uploadBlob", got, "image/png", &arrived.session).await.ok();
    assert!(missing_blobs(&h.b, &arrived.session).await.is_empty());
    (moved, exported)
}

/// bob's space repo moves from one vlpds host to another with his account:
/// the head (rev and hash), the records, the blob refs and an empty oplog
/// at the imported rev; check-space passes; carol's credential reads the
/// same records from the new host; the authority hears the new host's
/// writes.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn vlpds_export_imports_on_another_vlpds() {
    let h = two_hosts().await;
    let blob = fill_bob(&h).await;
    let before = head(&h.bob, &h.space).await.unwrap();
    let cred_a = h.carol_cred().await;
    let records_a = listed(&h.a.url, &cred_a, &h.space, &h.bob.did).await;
    assert_eq!(records_a.len(), 6);

    let (moved, exported) = move_bob(&h, &blob).await;
    let moved = &moved;
    assert_eq!(head(moved, &h.space).await, Some(before.clone()), "the head moves as it was");
    expect_set_hash_matches_store(moved, &h.space).await;
    check_space_ok(&h.b, &h.bob.did, &h.space).await;
    let ops = moved.get("com.atproto.space.listRepoOps", &[("space", &h.space), ("repo", &h.bob.did)]).await.ok();
    assert_eq!(ops["ops"], json!([]), "the oplog starts empty: {ops}");
    assert_eq!(ops["commit"]["rev"], json!(before.0));
    let lb = moved.get("com.atproto.space.listBlobs", &[("space", &h.space), ("repo", &h.bob.did)]).await.ok();
    assert_eq!(lb["cids"], json!([blob.0]), "{lb}");

    h.a.xrpc
        .post("com.atproto.server.deactivateAccount", &json!({}), &Auth::Bearer(h.bob.session_jwt.clone()))
        .await
        .ok();
    let r = get_repo_self(moved, &h.space).await;
    let served = verify_repo_car(&r.body, &h.space, &h.bob.did, &did_key(&h.b, &h.bob.did).await, true)
        .unwrap_or_else(|e| panic!("the new host's getRepo doesn't verify: {e}"));
    assert_eq!(served.index, exported.index);
    assert_eq!(served.records, exported.records);
    assert_eq!((served.commit.rev, served.commit.hash), (exported.commit.rev.clone(), exported.commit.hash.clone()));

    // carol's credential (from the authority on c) reads bob at b
    let cred = h.carol_cred().await;
    assert_eq!(listed(&h.b.url, &cred, &h.space, &h.bob.did).await, records_a);
    let latest =
        cred.get(&h.b.url, "com.atproto.space.getLatestCommit", &[("space", &h.space), ("repo", &h.bob.did)]).await;
    assert_eq!(latest.ok()["commit"]["rev"], json!(before.0));

    // bob writes on b: the authority on c hears the newer rev
    write(moved, &h.space, W::new().rkey("on-b").text("from the new host")).await.ok();
    let (rev, _) = head(moved, &h.space).await.unwrap();
    let mut seen = J::Null;
    for _ in 0..100 {
        seen = cred.get(&h.c.url, "com.atproto.space.listRepos", &[("space", &h.space)]).await.ok();
        let bob = seen["repos"].as_array().unwrap().iter().find(|x| x["did"] == json!(h.bob.did));
        if bob.is_some_and(|b| b["repoRev"] == json!(rev)) {
            break;
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    let bob = seen["repos"].as_array().unwrap().iter().find(|x| x["did"] == json!(h.bob.did));
    assert_eq!(
        bob.map(|b| &b["repoRev"]),
        Some(&json!(rev)),
        "the authority's listRepos after bob wrote on the new host: {seen}"
    );
    let mut s = Syncer::new(&h.b.url, &h.space, &h.bob.did, &did_key(&h.b, &h.bob.did).await, cred);
    s.full().await;
    let now = listed(&h.b.url, &h.carol_cred().await, &h.space, &h.bob.did).await;
    assert_eq!(now.len(), records_a.len() + 1);
    assert!(records_a.iter().all(|(p, c)| now.get(p) == Some(c)), "{now:?}");
    assert_eq!(s.set, now);
}

impl TwoHosts {
    pub(super) async fn carol_cred(&self) -> Cred {
        let token = delegation_token(&self.carol, &self.space).await;
        let holder = Holder::new();
        let r = exchange(&reqwest::Client::new(), &holder, &self.c.url, &self.space, &token, None).await;
        Cred { credential: r.ok()["credential"].as_str().unwrap().to_string(), holder, http: reqwest::Client::new() }
    }
}

// ---------------------------------------------------------------------------
// imports on one host, and refusals
// ---------------------------------------------------------------------------

/// alice governs a space on one host; bob may write in it.
struct One {
    net: Net,
    alice: SpaceClient,
    bob: SpaceClient,
    space: String,
}

async fn one() -> One {
    let net = Net::new(0).await;
    let (alice, bob) = (net.actor("alice", 0).await, net.actor("bob", 0).await);
    let space = net.create_space(&alice, SpaceOpts { members: &[&bob], ..Default::default() }).await;
    One { net, alice, bob, space }
}

fn records(b: RepoBuilder, n: usize) -> RepoBuilder {
    (0..n).fold(b, |b, i| {
        b.record(TEST_COLLECTION, &format!("imp{i:04}"), record(TEST_COLLECTION, &format!("imported {i}")))
    })
}

async fn nothing_written(sc: &SpaceClient, space: &str, what: &str) {
    assert_eq!(head(sc, space).await, None, "{what}: a refused import wrote a repo");
}

/// A repo bob never wrote here, signed with his own key (a restore from
/// his backup): imported at its rev, served, then written on; the authority
/// sequences it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn imports_a_restored_repo_and_takes_writes_after() {
    let o = one().await;
    let s = &o.net.pds[0];
    let rev = rev_ago(Duration::from_secs(90));
    let b = records(RepoBuilder::new(&o.space, &o.bob.did, &rev), 7);
    let built = b.build(&*account_key(s, &o.bob.did).await);
    let out = import_repo(&o.bob, &o.space, &built.car()).await.ok();
    assert_eq!((out["rev"].clone(), out["records"].clone()), (json!(rev), json!(7)), "{out}");
    assert_eq!(head(&o.bob, &o.space).await, Some((rev.clone(), b.set().digest().to_vec())));
    check_space_ok(s, &o.bob.did, &o.space).await;
    let writers = o.net.await_writer(&o.alice, &o.space, &o.bob.did).await;
    assert!(writers.contains(&o.bob.did), "the authority sequences the imported repo: {writers:?}");

    let cred = o.net.credential_for(&o.alice, &o.space).await;
    let got = listed(&s.url, &cred, &o.space, &o.bob.did).await;
    let want: std::collections::BTreeMap<String, String> =
        built.records.iter().map(|(p, c, _)| (p.clone(), c.to_string())).collect();
    assert_eq!(got, want);
    write(&o.bob, &o.space, W::new().rkey("later").text("after the restore")).await.ok();
    let (after, _) = head(&o.bob, &o.space).await.unwrap();
    assert!(after > rev);
    expect_set_hash_matches_store(&o.bob, &o.space).await;
}

/// The reference's verifyRepoCarFull refuses each of these, and so does
/// the import, writing nothing: a record block whose bytes don't hash to
/// its CID, an index entry naming another CID, a missing record block, an
/// extra block, blocks out of index order, the index before the commit.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn refuses_a_tampered_car() {
    let o = one().await;
    let s = &o.net.pds[0];
    let key = account_key(s, &o.bob.did).await;
    let dk = key.did_key();
    let b = records(RepoBuilder::new(&o.space, &o.bob.did, &rev_ago(Duration::from_secs(60))), 4);
    let built = b.build(&key);
    assert!(verify_repo_car(&built.car(), &o.space, &o.bob.did, &dk, true).is_ok());

    let mut cases: Vec<(&str, Vec<u8>)> = vec![
        (
            "a record's bytes changed",
            built.car_with(|bl| bl[3].1 = record_block(&record(TEST_COLLECTION, "tampered")).1),
        ),
        ("a record block missing", built.car_with(|bl| drop(bl.remove(4)))),
        ("an extra block", built.car_with(|bl| bl.push(record_block(&record(TEST_COLLECTION, "extra"))))),
        ("records out of index order", built.car_with(|bl| bl.swap(2, 3))),
        ("the index before the commit", built.car_with(|bl| bl.swap(0, 1))),
    ];
    // an index entry swapped for another record's CID: still a valid block,
    // but it no longer folds to the signed hash
    let mut swapped = built.records.iter().map(|(p, c, _)| (p.clone(), *c)).collect::<Vec<_>>();
    swapped[0].1 = record_block(&record(TEST_COLLECTION, "another")).0;
    let ib = index_block(&swapped);
    let icid = Cid::dag_cbor(&ib);
    let mut blocks = vec![(built.commit_cid, built.commit_block.clone()), (icid, ib)];
    blocks.extend(built.records.iter().map(|(_, c, b)| (*c, b.clone())));
    cases.push(("an index entry naming another CID", write_car(&[built.commit_cid, icid], &blocks)));
    cases.push(("not a CAR", b"not a car at all".to_vec()));
    cases.push(("one root", {
        let all = built.car_with(|_| {});
        let (_, bl) = vlsync_atproto::car::read_car(&all).unwrap();
        let owned: Vec<(Cid, Vec<u8>)> = bl.iter().map(|(c, b)| (*c, b.to_vec())).collect();
        write_car(&[built.commit_cid], &owned)
    }));

    for (what, car) in &cases {
        assert!(
            verify_repo_car(car, &o.space, &o.bob.did, &dk, true).is_err(),
            "{what}: the reference would accept it"
        );
        let r = import_repo(&o.bob, &o.space, car).await;
        assert_eq!(r.status, 400, "{what}: {}", r.text());
        nothing_written(&o.bob, &o.space, what).await;
    }
    import_repo(&o.bob, &o.space, &built.car()).await.ok();
}

/// A commit signed by a key that isn't the DID's, a MAC that doesn't bind
/// the hash, and a hash the records don't fold to are refused.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn refuses_a_bad_signature_or_mac() {
    let o = one().await;
    let s = &o.net.pds[0];
    let key = account_key(s, &o.bob.did).await;
    let b = records(RepoBuilder::new(&o.space, &o.bob.did, &rev_ago(Duration::from_secs(60))), 3);

    let wrong_key = b.build(&vlsync_atproto::crypto::Keypair::generate());
    let mut bad_mac = b.build(&key);
    bad_mac.commit.mac[0] ^= 1;
    bad_mac.commit_block = commit_block(&bad_mac.commit);
    bad_mac.commit_cid = Cid::dag_cbor(&bad_mac.commit_block);
    // the MAC rebound to another hash, as anyone holding a commit can: the
    // signature and MAC verify, the index doesn't fold to it
    let mut rebound = b.build(&key);
    let mut other = b.set();
    other.add("com.example.x/y/bafyreie5737gdxlw5i64vzichcalba3z2v5n6icifvx5xytvske7mr3hpm");
    let ctx = vlpds::space::commit::encode_ctx(
        &vlpds::space::commit::CommitCtx { space: &o.space, author: &o.bob.did, rev: &rebound.commit.rev },
        &rebound.commit.ikm,
    )
    .unwrap();
    rebound.commit.hash = other.digest().to_vec();
    rebound.commit.mac = vlpds::space::commit::mac(&rebound.commit.ikm, &ctx, &rebound.commit.hash).to_vec();
    rebound.commit_block = commit_block(&rebound.commit);
    rebound.commit_cid = Cid::dag_cbor(&rebound.commit_block);

    let dk = key.did_key();
    for (what, built) in
        [("another key's signature", wrong_key), ("a broken MAC", bad_mac), ("a rebound hash", rebound)]
    {
        let car = built.car();
        assert!(verify_repo_car(&car, &o.space, &o.bob.did, &dk, true).is_err(), "{what}");
        let r = import_repo(&o.bob, &o.space, &car).await;
        assert_eq!(r.status, 400, "{what}: {}", r.text());
        nothing_written(&o.bob, &o.space, what).await;
    }
}

/// alice's repo (signed by alice for this space) imported by bob, bob's
/// repo for another space imported into this one, and a CAR whose commit
/// names another space are refused.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn refuses_another_dids_or_another_spaces_repo() {
    let o = one().await;
    let s = &o.net.pds[0];
    let rev = rev_ago(Duration::from_secs(60));
    let alices = records(RepoBuilder::new(&o.space, &o.alice.did, &rev), 2).build(&*account_key(s, &o.alice.did).await);
    let r = import_repo(&o.bob, &o.space, &alices.car()).await;
    assert_eq!(r.status, 400, "another DID's repo: {}", r.text());
    nothing_written(&o.bob, &o.space, "another DID's repo").await;

    let other = o.net.create_space(&o.alice, SpaceOpts { members: &[&o.bob], ..Default::default() }).await;
    let for_other = records(RepoBuilder::new(&other, &o.bob.did, &rev), 2).build(&*account_key(s, &o.bob.did).await);
    let r = import_repo(&o.bob, &o.space, &for_other.car()).await;
    assert_eq!(r.status, 400, "another space's repo: {}", r.text());
    nothing_written(&o.bob, &o.space, "another space's repo").await;
    // where it belongs, it imports
    import_repo(&o.bob, &other, &for_other.car()).await.ok();
}

/// `--space-repo-max-records` (100k) bounds an import as it bounds writes.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn refuses_a_repo_over_the_record_cap() {
    let o = one().await;
    let s = &o.net.pds[0];
    let key = account_key(s, &o.bob.did).await;
    let rev = rev_ago(Duration::from_secs(60));
    let mut b = RepoBuilder::new(&o.space, &o.bob.did, &rev);
    for i in 0..100_001u32 {
        b.records
            .insert(format!("{TEST_COLLECTION}/c{i:06}"), record_block(&json!({"$type": TEST_COLLECTION, "i": i})));
    }
    let car = b.build(&key).car();
    let r = import_repo(&o.bob, &o.space, &car).await;
    refused_mentioning(&r, &["limit", "max"]);
    nothing_written(&o.bob, &o.space, "over the cap").await;
    // at the cap it goes in
    b.records.pop_last();
    import_repo(&o.bob, &o.space, &b.build(&key).car()).await.ok();
}

/// Importing a repo is writing it: an account that isn't a member of the
/// space, or is one without write, is refused as its writes would be, and
/// accepted once the authority lets it write.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn refuses_a_space_the_account_cant_write_in() {
    let net = Net::new(0).await;
    let (alice, carol) = (net.actor("alice", 0).await, net.actor("carol", 0).await);
    let space = net.create_space(&alice, SpaceOpts::default()).await;
    let s = &net.pds[0];
    let built = records(RepoBuilder::new(&space, &carol.did, &rev_ago(Duration::from_secs(60))), 2)
        .build(&*account_key(s, &carol.did).await);
    let r = import_repo(&carol, &space, &built.car()).await;
    refused_mentioning(&r, &["member", "not authorized", "forbidden", "write"]);
    nothing_written(&carol, &space, "not a member").await;
    put_member(&alice, &space, &carol, true, false).await.ok();
    let r = import_repo(&carol, &space, &built.car()).await;
    refused_mentioning(&r, &["member", "not authorized", "forbidden", "write"]);
    nothing_written(&carol, &space, "a member without write").await;
    put_member(&alice, &space, &carol, true, true).await.ok();
    import_repo(&carol, &space, &built.car()).await.ok();
}

/// Space data is OAuth-only (brief, FINAL): a password session and app
/// passwords are refused, and an OAuth grant must allow writing in the
/// space.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn import_is_oauth_only() {
    let o = one().await;
    let s = &o.net.pds[0];
    let built = records(RepoBuilder::new(&o.space, &o.bob.did, &rev_ago(Duration::from_secs(60))), 2)
        .build(&*account_key(s, &o.bob.did).await);
    let car = built.car();
    let session = Auth::Bearer(o.bob.session_jwt.clone());
    let mut auths = vec![("password session", session.clone())];
    for privileged in [false, true] {
        let ap = s
            .xrpc
            .post(
                "com.atproto.server.createAppPassword",
                &json!({"name": format!("imp-{privileged}"), "privileged": privileged}),
                &session,
            )
            .await
            .ok();
        let sess = s.create_session(&o.bob.did, ap["password"].as_str().unwrap()).await.ok();
        auths.push(("app password", Auth::Bearer(sess["accessJwt"].as_str().unwrap().into())));
    }
    auths.push(("no auth", Auth::None));
    for (what, auth) in &auths {
        let r = import_repo_as(&s.url, auth, &o.space, &car).await;
        assert!(r.status == 401 || r.status == 403, "{what}: {}", r.text());
        nothing_written(&o.bob, &o.space, what).await;
    }
    let read_only = regrant(&o.bob, &format!("space:{TEST_SPACE_TYPE}?authority=*&collection=*&action=read")).await;
    let r = import_repo(&read_only, &o.space, &car).await;
    assert!((400..500).contains(&r.status), "a read-only grant: {}", r.text());
    nothing_written(&o.bob, &o.space, "a read-only grant").await;
    import_repo(&o.bob, &o.space, &car).await.ok();
}

/// After a key rotation the DID's current key is another one: a CAR signed
/// by a key the DID held at the commit's rev (its PLC history) imports, one
/// signed by a key it never had doesn't, and neither does one by a key it
/// held but long before the rev.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn import_verifies_against_the_key_held_at_the_rev() {
    let h = two_hosts().await;
    let old_key = account_key(&h.a, &h.bob.did).await;
    let rev = rev_ago(Duration::from_secs(60));
    let built =
        |key: &vlsync_atproto::crypto::Keypair| records(RepoBuilder::new(&h.space, &h.bob.did, &rev), 2).build(key);
    let b_did = h.b.pds_did().await;
    let sa = service_jwt(&h.bob, &b_did, "com.atproto.server.createAccount").await;
    let arrived = arrive(&h.b, &h.bob.did, sa).await;
    complete_move(&h.docs, &h.b, &arrived).await;
    let moved = arrived.oauth(&h.b).await;
    assert_ne!(did_key(&h.b, &h.bob.did).await, old_key.did_key(), "the DID's key rotated");

    let never = built(&vlsync_atproto::crypto::Keypair::generate());
    let r = import_repo(&moved, &h.space, &never.car()).await;
    assert_eq!(r.status, 400, "a key the DID never had: {}", r.text());
    assert_eq!(r.json["error"], json!("InvalidCommit"), "{}", r.text());
    nothing_written(&moved, &h.space, "a key the DID never had").await;

    import_repo(&moved, &h.space, &built(&old_key).car()).await.ok();
    assert_eq!(head(&moved, &h.space).await.map(|h| h.0), Some(rev));
}

/// An import over a repo that's there replaces it with the snapshot at a
/// newer rev, as com.atproto.repo.importRepo does: the old records go, the
/// new ones are served, check-space is clean. The same rev with the same
/// records is a no-op 200 (a retried import); an older rev, or the same
/// rev with other records, is refused, and so is a second import while one
/// runs.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn import_over_a_repo_replaces_it() {
    let o = one().await;
    let s = &o.net.pds[0];
    let key = account_key(s, &o.bob.did).await;
    write(&o.bob, &o.space, W::new().rkey("live").text("written here")).await.ok();
    let first = rev_ago(Duration::from_secs(30));
    let mut b = RepoBuilder::new(&o.space, &o.bob.did, &first);
    for i in 0..3 {
        b.records.insert(format!("{TEST_COLLECTION}/old{i}"), record_block(&json!({"$type": TEST_COLLECTION, "i": i})));
    }
    let r = import_repo(&o.bob, &o.space, &b.build(&key).car()).await;
    assert_eq!(r.status, 400, "a rev older than the repo's: {}", r.text());

    let newer = vlsync_atproto::tid::Tid::from_parts(vlsync_atproto::tid::now_micros(), 0).to_string();
    let mut b = RepoBuilder::new(&o.space, &o.bob.did, &newer);
    for i in 0..2 {
        b.records.insert(format!("{TEST_COLLECTION}/new{i}"), record_block(&json!({"$type": TEST_COLLECTION, "n": i})));
    }
    let built = b.build(&key);
    // an import already running holds the space repo
    let sp = s.app.spaces.as_ref().unwrap();
    let sid = vlpds::state::space_id(&o.space);
    assert!(sp.begin_import(&o.bob.did, sid, 7));
    let r = import_repo(&o.bob, &o.space, &built.car()).await;
    assert_eq!(r.status, 400, "a second import: {}", r.text());
    assert!(r.text().contains("in progress"), "{}", r.text());
    sp.end_import(&o.bob.did, sid, 7);

    let out = import_repo(&o.bob, &o.space, &built.car()).await.ok();
    assert_eq!((out["rev"].clone(), out["records"].clone()), (json!(newer), json!(2)), "{out}");
    let mut got: Vec<String> =
        all_records(&o.bob, &o.space).await.iter().map(|r| r["rkey"].as_str().unwrap().to_string()).collect();
    got.sort();
    assert_eq!(got, ["new0", "new1"], "the snapshot replaced the repo");
    assert_eq!(head(&o.bob, &o.space).await.map(|h| h.0), Some(newer.clone()));
    expect_set_hash_matches_store(&o.bob, &o.space).await;
    check_space_ok(s, &o.bob.did, &o.space).await;

    // the same snapshot again (a retried import, signed afresh): a 200 that
    // writes nothing
    o.net.await_writer(&o.alice, &o.space, &o.bob.did).await;
    let p = s.app.partition(&o.bob.did).ok().unwrap();
    let outbox = || p.db.get(vlpds::state::space_outbox_key(&o.bob.did, &sid));
    let ordinal = settled_ordinal(s).await;
    let sp_row = outbox().await.unwrap();
    let again = b.build(&key);
    assert_ne!(again.commit_cid, built.commit_cid, "a fresh signature");
    let out = import_repo(&o.bob, &o.space, &again.car()).await.ok();
    assert_eq!((out["rev"].clone(), out["records"].clone()), (json!(newer), json!(2)), "{out}");
    assert_eq!(s.app.log.next_ordinal(), ordinal, "a same-content import wrote a log segment");
    assert_eq!(outbox().await.unwrap(), sp_row, "a same-content import touched the outbox");
    assert_eq!(head(&o.bob, &o.space).await.map(|h| h.0), Some(newer.clone()));

    // the same rev with other records is refused, and so is an older one
    let mut other = RepoBuilder::new(&o.space, &o.bob.did, &newer);
    other.records.insert(format!("{TEST_COLLECTION}/new0"), record_block(&json!({"$type": TEST_COLLECTION, "n": 9})));
    let r = import_repo(&o.bob, &o.space, &other.build(&key).car()).await;
    assert_eq!(r.status, 400, "the same rev with other records: {}", r.text());
    let r = import_repo(&o.bob, &o.space, &RepoBuilder::new(&o.space, &o.bob.did, &first).build(&key).car()).await;
    assert_eq!(r.status, 400, "an older rev: {}", r.text());
    let mut got: Vec<String> =
        all_records(&o.bob, &o.space).await.iter().map(|r| r["rkey"].as_str().unwrap().to_string()).collect();
    got.sort();
    assert_eq!(got, ["new0", "new1"], "a refused import changed the repo");
}

/// The node log's next ordinal once nothing has been written for 300 ms.
async fn settled_ordinal(s: &TestServer) -> u64 {
    let mut last = s.app.log.next_ordinal();
    for _ in 0..100 {
        tokio::time::sleep(Duration::from_millis(300)).await;
        let now = s.app.log.next_ordinal();
        if now == last {
            return now;
        }
        last = now;
    }
    panic!("the node log never settled");
}

/// A key the DID rotated away from signs only commits from before the
/// rotation (with its 5 min of slack): a former host can't keep minting
/// importable commits after the account left.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_past_key_signs_only_revs_before_it_was_rotated_away() {
    let h = two_hosts().await;
    let old_key = account_key(&h.a, &h.bob.did).await;
    let b_did = h.b.pds_did().await;
    let sa = service_jwt(&h.bob, &b_did, "com.atproto.server.createAccount").await;
    let arrived = arrive(&h.b, &h.bob.did, sa).await;
    complete_move(&h.docs, &h.b, &arrived).await;
    // the move's rotation, 30 min ago
    h.docs.lock().unwrap().backdate(&h.bob.did, Duration::from_secs(1800));
    let moved = arrived.oauth(&h.b).await;
    let built = |ago: u64| {
        records(RepoBuilder::new(&h.space, &h.bob.did, &rev_ago(Duration::from_secs(ago))), 2).build(&old_key)
    };
    // 20 min ago: after the rotation and its slack
    let r = import_repo(&moved, &h.space, &built(1200).car()).await;
    assert_eq!((r.status, r.json["error"].as_str()), (400, Some("InvalidCommit")), "{}", r.text());
    nothing_written(&moved, &h.space, "a past key after its rotation").await;
    // 27 min ago: within the slack
    let r = import_repo(&moved, &h.space, &built(1620).car()).await;
    assert_eq!(r.status, 200, "{}", r.text());
    // and long before it, but older than what's there now
    let r = import_repo(&moved, &h.space, &built(2400).car()).await;
    assert_eq!(r.status, 400, "{}", r.text());
}

/// A space deleted and made again is a new space: a repo from before
/// (signed by any key the account held then) doesn't come back into it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_repo_from_before_the_space_was_made_again_is_refused() {
    let o = one().await;
    let s = &o.net.pds[0];
    let key = account_key(s, &o.alice.did).await;
    let old = records(RepoBuilder::new(&o.space, &o.alice.did, &rev_ago(Duration::from_secs(600))), 2).build(&key);
    write(&o.alice, &o.space, W::new().rkey("live").text("before the delete")).await.ok();
    o.alice.post("com.atproto.simplespace.deleteSpace", json!({"space": o.space})).await.ok();
    let skey = last_segment(&o.space).to_string();
    let again = o
        .alice
        .post(
            "com.atproto.simplespace.createSpace",
            json!({"spaceType": TEST_SPACE_TYPE, "skey": skey, "readPolicy": member_list(), "writePolicy": member_list(), "appAccess": open()}),
        )
        .await;
    assert_eq!(again.ok()["uri"], json!(o.space));
    let r = import_repo(&o.alice, &o.space, &old.car()).await;
    refused_mentioning(&r, &["predates the space"]);
    nothing_written(&o.alice, &o.space, "a repo from before").await;
    // a repo of the space as it is now goes in
    let now = records(RepoBuilder::new(&o.space, &o.alice.did, &rev_ago(Duration::from_secs(1))), 2).build(&key);
    import_repo(&o.alice, &o.space, &now.car()).await.ok();
}

/// The same with the authority on another node of a cluster: the check
/// runs at the owner of the authority's shard, not skipped.
#[tokio::test(flavor = "multi_thread", worker_threads = 8)]
async fn a_repo_from_before_the_space_was_made_again_is_refused_across_a_cluster() {
    let (bucket, plc) = (Arc::new(object_store::memory::InMemory::new()), super::cluster::Plc::start().await);
    let n1 = super::cluster::node("imr-1", &bucket, 6, &plc).await;
    let n2 = super::cluster::node("imr-2", &bucket, 6, &plc).await;
    balanced(&[&n1, &n2]).await;
    let alice = SpaceClient::new(&n1, &unique_name("imra"), FULL_SCOPE).await;
    let bob = SpaceClient::new(&n2, &unique_name("imrb"), FULL_SCOPE).await;
    let make = || async {
        let body = json!({"spaceType": TEST_SPACE_TYPE, "skey": "again", "readPolicy": member_list(), "writePolicy": member_list(), "appAccess": open()});
        let space =
            alice.post("com.atproto.simplespace.createSpace", body).await.ok()["uri"].as_str().unwrap().to_string();
        put_member(&alice, &space, &bob, true, true).await.ok();
        space
    };
    let space = make().await;
    let key = account_key(&n2, &bob.did).await;
    let old = records(RepoBuilder::new(&space, &bob.did, &rev_ago(Duration::from_secs(600))), 2).build(&key);
    alice.post("com.atproto.simplespace.deleteSpace", json!({"space": space})).await.ok();
    assert_eq!(make().await, space);
    let r = import_repo(&bob, &space, &old.car()).await;
    refused_mentioning(&r, &["predates the space"]);
    nothing_written(&bob, &space, "a repo from before, across the cluster").await;
    let now = records(RepoBuilder::new(&space, &bob.did, &rev_ago(Duration::from_secs(1))), 2).build(&key);
    import_repo(&bob, &space, &now.car()).await.ok();
}
